INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('f1a92df4-a271-4f90-beb5-662c725b2661','db618e68-0656-4b9b-b308-81e071faf745','Mvula','complete','{"age":"TBD","era":"500–1300 AD-inspired fantasy","name":"Mvula","race":"Restless Spirit","alias":"","gender":"Male","titles":"The Forgotten Scout\nThe Shadow of the Crevice\nThe Hunger Behind the Dead Eye","subrace":"Ghede-Baka","summary":"Mvula was once a scout of the Stone Mountains who died alone in a mountain crevice without receiving his final rites. Forgotten by the living, his abandoned spirit became a corrupted Ghede-Baka. During the Great Drought, Xolani forcibly bound Mvula through the Binding Cadence, creating a parasitic spiritual connection that ultimately tethered Mvula to Xolani''s Dead Eye.","heritage":"Kwaye-Zulu","homeland":"Stone Mountains","pronouns":"He/Him","birthDate":"TBD","nicknames":"","occupation":"Former scout","affiliation":"Xolani","apparentAge":"Adult","canonStatus":"Canon","nameMeaning":"TBD","nationality":"","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Spirit-bound to Xolani","elementalHeritage":""}','{"build":["Emaciated","Elongated","Gaunt"],"nails":["Dark elongated nails"],"eyeHex":["#E9E8DF"],"height":"TBD","makeup":"","weight":"Weightless spirit","hairHex":["#11100F"],"skinHex":["#171615","#494642"],"eyeColor":["White spirit-light"],"grooming":"Spirit manifestation","skinTone":["Charcoal black","Ash grey"],"wardrobe":"Tattered scout clothing\nWeathered wraps\nShredded outer layers","hairColor":["Charcoal black"],"hairStyle":"Flowing shadow and drifting ash","accessories":"","faceDetails":["Hollow facial structure","Sunken cheeks","Gaunt jawline","Shadowed features"],"hairTexture":["Smoke-like","Shadow-like"],"colorPalette":"Charcoal black\nAsh grey\nBone white\nSmoke grey\nMoonlit silver","dominantHand":"TBD","outfitColors":"#11100F\n#292725\n#55514C\n#B8B5AD","alternateForm":["Partial shadow manifestation","Full spirit manifestation"],"clothingStyle":"Ruined Stone Mountains scout clothing fused into his spectral body. Clothing should appear ancient, practical, torn, and partially consumed by smoke.","appearanceNotes":"Mvula should remain recognizably humanoid while clearly supernatural. His silhouette is tall, thin, and unnerving, with charcoal smoke continuously peeling from his body. His elongated spectral arm frequently manifests over Xolani''s shoulder and mirrors Xolani''s Asalato movements.","outfitMaterials":["Tattered cloth","Weathered leather","Spectral smoke","Ash"],"postureMovement":["Predatory hovering","Unnatural stillness","Smoke-like movement","Clings behind Xolani"],"signatureOutfit":"Fragments of his former scout clothing remain within his manifestation as shredded, smoke-darkened layers that dissolve into ash and shadow. His silhouette should suggest the remains of a mountain scout rather than ornate ceremonial clothing.","distinguishingFeatures":["Charcoal smoke body","White spirit-light eyes","Elongated fingers","Emaciated arms","Ash-fractured form","Smoke-shrouded face","Unstable body edges"]}','{"fears":["Being forgotten","The Void of the Forgotten","Xolani dying","Losing his final connection to life"],"goals":["Remain remembered","Preserve his existence","Make Xolani understand his suffering"],"beliefs":["The forgotten suffer twice","Spirits should not be enslaved","Memory preserves existence"],"culture":["Kwaye-Zulu","Stone Mountains"],"lineage":"Kwaye-Zulu","storyArc":"Mvula begins consumed by hatred toward the man who enslaved him. He torments Xolani through visions, sensory manipulation, and attempts to sabotage his rhythm. Xolani''s refusal to erase Mvula''s humanity slowly changes their bond, and Mvula begins protecting the person he once wanted to destroy because Xolani has become the only living witness to who Mvula was.","backstory":"Mvula was a scout from the Stone Mountains who was left to die in a mountain crevice during a tribal war. Denied final rites and eventually forgotten, his spirit remained trapped in bitterness and grief until he became a corrupted Ghede-Baka. During the Great Drought, Xolani found Mvula and forcibly imprisoned him through the Binding Cadence to power a ritual that brought Black Rain to Kwaye-Zulu. Mvula retaliated by spiritually overwriting Xolani''s left eye, becoming permanently tethered to the Dead Eye.","childhood":"TBD","lifestyle":["Exists through Xolani''s Dead Eye","Observes the spirit world","Whispers to Xolani","Interferes with Xolani''s senses","Protects his host when threatened"],"storyRole":"Mvula is both Xolani''s tormentor and reluctant guardian. He embodies the consequences of Xolani''s forbidden ritual while giving a voice to the forgotten dead. His constant presence turns Xolani''s spiritual abilities into both a weapon and an ongoing punishment.","birthplace":"Kwaye-Zulu, Stone Mountains","psychology":["Terrified of being forgotten","Resents Xolani","Carries abandonment trauma","Emotionally dependent on Xolani","Hides concern behind hostility"],"motivations":["Avoid being forgotten","Preserve his existence","Punish Xolani","Protect his remaining connection","Have his life remembered"],"personality":["Bitter","Vindictive","Observant","Hostile","Sarcastic","Manipulative","Fearful","Protective","Lonely"],"voiceSpeech":["Distorted male whisper","Ancient tone","Bitter delivery","Sardonic speech","Low spectral voice"],"likesDislikes":["Loved the smell of rain","Notices mountain flowers","Hates being forgotten","Hates spiritual enslavement","Resents forced binding"],"majorLifeEvents":"Serves as a Stone Mountains scout\nAbandoned during tribal war\nDies alone in mountain crevice\nDenied final rites\nBecomes a Ghede-Baka\nEncountered by Xolani\nForcibly bound by Binding Cadence\nPowers the Black Rain ritual\nCreates Xolani''s Dead Eye\nBecomes tethered to Xolani\nBegins reluctantly protecting Xolani"}','{"weapons":"Spectral influence","strengths":"Spirit perception\nPsychological warfare\nSensory manipulation\nSpectral movement\nDefensive instinct\nIntimidation","weaknesses":"Sacred salt\nFlorida Water\nConsecrated ground\nRitual cleansing","combatStyle":["Psychological warfare","Spiritual disruption","Fear induction","Sensory attacks","Defensive intervention"],"limitations":["Bound to Xolani","Cannot freely leave the bond","Xolani''s survival affects him","Manifestation depends on spiritual influence"],"powerSource":["Restless spirit energy","Dead Eye bond","Grey Space","Spiritual connection to Xolani"],"abilityNotes":"Mvula''s Choking Miasma creates crushing grief and hopelessness around Xolani. His Echoing Scream causes the target''s spirit to recoil from the body. Through Eye-Lock and the Direct Feed, he can expose a target to the horrifying Grey Space perceived through Xolani''s Dead Eye.","combatProfile":"Mvula fights indirectly through Xolani and the surrounding spirit space. He overwhelms enemies with despair, spiritual screams, visions, and sensory distortion while manifesting spectral limbs to influence combat. Although he frequently sabotages Xolani, his survival is tied to his host, causing him to intervene when Xolani faces lethal danger.","weaponDetails":"Mvula does not rely on a conventional physical weapon. He attacks through spiritual pressure, sensory manipulation, spectral manifestations, and his connection to Xolani''s Dead Eye and Asalato.","transformations":"Partial manifestation\nFull spirit manifestation","primaryAbilities":"Choking Miasma\nEchoing Scream\nEye-Lock\nSpectral Manifestation","secondaryAbilities":"Sensory manipulation\nSpectral guidance\nMotor interference\nDeath visions\nSpirit perception","signatureTechniques":"Direct Feed\nSpectral Intervention\nRhythm Sabotage","transformationDetails":"Mvula usually exists as a shadow clinging to Xolani''s back or within the Dead Eye. When his influence intensifies, more of his emaciated charcoal form emerges through smoke and ash. His elongated arms can manifest around Xolani and mimic or interfere with his movements."}','{"allies":"Xolani — Host, former captor, and reluctant companion","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"Xolani\nKwaye-Zulu\nStone Mountains\nGrey Space\nDead Eye\nAltar of the Unburied","relationshipNotes":"Mvula initially views Xolani as his jailer after being forcibly bound during the Great Drought. He tortures Xolani through visions, whispers, sensory overlap, and rhythm sabotage, yet protects him whenever death threatens them both. Xolani''s determination to remember Mvula as a man rather than a monster gradually transforms their relationship from pure hatred into reluctant mutual recognition."}','{"tbdFields":"Birth date\nExact age at death\nPronunciation\nName meaning\nHeight\nDominant hand\nParents\nSiblings\nChildhood\nExact appearance before death","canonLocks":"Male spirit\nFormer Stone Mountains scout\nOriginates from Kwaye-Zulu\nDied in a mountain crevice\nDenied final rites\nBecame a Ghede-Baka\nForcibly bound by Xolani\nTethered to Xolani''s Dead Eye\nCharcoal shadow manifestation\nWhite spirit-light eyes\nElongated spectral limbs\nFears being forgotten\nProtects Xolani reluctantly","galleryUrl":"","mediaNotes":"Use Mvula''s established portrait and full-body artwork as visual continuity references. Future artwork should preserve his charcoal-and-ash palette, spectral white eyes, gaunt silhouette, elongated fingers, smoky manifestation, and visual connection to Xolani''s Dead Eye.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/f1a92df4-a271-4f90-beb5-662c725b2661/portrait/1790321436461-mvula-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Needed\nAlternate / True Form — Needed\nFull-Body Front — Done\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Needed\nEye Reference — Needed\nOutfit Breakdown — Needed\nExpression Sheet — Needed\nCombat Reference — Needed","productionNotes":"Mvula must remain visually connected to the established Xolani design without resembling Xolani himself. Preserve his emaciated charcoal spirit body, ash-grey fractures, white spirit-light eyes, elongated limbs, smoke-like edges, and remnants of practical Stone Mountains scout clothing. His design should communicate that he was once human before becoming a corrupted restless spirit.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/f1a92df4-a271-4f90-beb5-662c725b2661/reference/1790321444313-mvula-reference-production-sheet.png","alternateFormUrl":""}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/f1a92df4-a271-4f90-beb5-662c725b2661/portrait/1790321436461-mvula-character-portrait.png',6,1,1,'c6c8934d-b274-44f7-a1a6-a6f8f959654b','4b626524-5522-485d-b40f-6490debf9f06','e2b28b7d-4073-4cf3-b937-7090a913102c','7fe566b0-b4c5-4bef-8c77-0ab21b2a3ff4','2026-09-25T17:22:35.039401+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('7538e2ae-03cd-4c2f-a116-05e51b4fa245','db618e68-0656-4b9b-b308-81e071faf745','Ruchika','complete','{"age":"TBD","era":"500–1300 AD-inspired fantasy era","name":"Ruchika","race":"Dragon","alias":"The Bone Dragon","gender":"Male","titles":"The Bone Dragon\nThe Ivory Artisan\nThe Wandering Craftsman","subrace":"Elemental Dragon","summary":"Ruchika is the Bone Dragon, born from Earth and Water. He is a disciplined craftsman, powerful defender, and natural wanderer who lives in the Shifting Sands with his brother Gaius.","heritage":"Indian + Asian","homeland":"Shifting Sands","pronouns":"He/Him","birthDate":"TBD","nicknames":"Ruchi","occupation":"Master Craftsman and Wanderer","affiliation":"Terrax and Leviathans bloodline","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"Major","pronunciation":"Roo-chee-kah","currentResidence":"Shifting Sands","elementalHeritage":"Earth + Water"}','{"build":["Tall","Lean-muscular","Broad-shouldered","Athletic"],"nails":[{"hex":"#C89B83","name":"Natural"}],"eyeHex":[{"hex":"#D89B32","name":"Golden Amber"}],"height":"Approximately 6''3\" / 190 cm","makeup":"","weight":"TBD","hairHex":[{"hex":"#151218","name":"Black"}],"skinHex":[{"hex":"#9A6548","name":"Warm Medium Brown"}],"eyeColor":["Golden amber"],"grooming":"Clean and practical","skinTone":["Warm medium-brown"],"wardrobe":"Travel outfit\nCrafting outfit\nCombat outfit\nCeremonial attire","hairColor":["Black"],"hairStyle":"Long layered hair worn loose","accessories":"Living bone bracers\nCrafting tools\nTravel satchel\nUtility belt","faceDetails":["Defined jawline","High cheekbones","Straight nose","Calm expression","Thick dark eyebrows"],"hairTexture":["Thick","Slightly wavy"],"colorPalette":"Ivory — #E8DFC8\nMidnight Blue — #182A3D\nSlate Gray — #4E5963\nEarth Brown — #654A3A\nGolden Amber — #D89B32\nBlack — #151218","dominantHand":"TBD","outfitColors":"Angrakha — Midnight Blue #182A3D\nDhoti — Charcoal #292A2D\nSash — Earth Brown #654A3A\nBone Bracers — Ivory #E8DFC8\nTrim — Muted Gold #B88A3D","alternateForm":["True Bone Dragon Form"],"clothingStyle":"Early-medieval Indian-inspired clothing with practical layered construction and bone accents.","appearanceNotes":"His design combines grounded Earth elements with subtle Water influence. Bone should always appear smooth, pale ivory, and organically grown rather than metallic.","outfitMaterials":["Woven cotton","Linen","Leather","Living bone"],"postureMovement":["Upright posture","Controlled movement","Heavy grounded stance","Quiet footsteps"],"signatureOutfit":"Dark layered angrakha with a wrapped dhoti, waist sash, living bone bracers, leather sandals, and practical crafting gear.","distinguishingFeatures":["Golden amber eyes","Long black hair","Living ivory bone","Bone can emerge from his body","Natural bone bracers"]}','{"fears":["Failing to protect family","Losing control of his creations","Seeing his work used irresponsibly"],"goals":["Perfect Bone craftsmanship","Discover rare materials","Protect Ife","Continue wandering","Preserve useful knowledge"],"beliefs":["Strength should have purpose","Creation is as important as destruction","Nothing strong is built carelessly","Freedom and responsibility can coexist"],"culture":["Terrax elemental traditions","Leviathans aquatic traditions","Shifting Sands culture","Wandering artisan traditions"],"lineage":"Son of Terrax and Leviathans","storyArc":"Ruchika begins as a self-contained wanderer focused on craft and family. His travels gradually pull him into wider conflicts where his ability to create and protect becomes increasingly important.","backstory":"Born from Earth and Water, Ruchika developed Bone as his unique elemental expression. Rather than pursuing destruction, he became a craftsman who uses his power to build, repair, protect, and create. He eventually made his home in the Shifting Sands with his brother Gaius, but his wandering nature keeps him traveling throughout the Umbral World.","childhood":"Ruchika grew up between two ancient elemental bloodlines. Terrax shaped his patience and structural thinking, while Leviathans influenced the adaptive and regenerative nature of his magic.","lifestyle":["Lives in the Shifting Sands","Frequently travels","Crafts weapons and tools","Studies natural materials","Explores ruins and distant lands"],"storyRole":"A wandering Bone Dragon and master craftsman based in the Shifting Sands. His travels allow him to appear across many regions of the Umbral World.","birthplace":"TBD","psychology":["Values stability","Shows love through actions","Needs personal freedom","Protective of family","Finds peace through craftsmanship"],"motivations":["Protect his family","Master his craft","Explore the Umbral World","Understand unusual materials","Create objects that endure"],"personality":["Calm","Disciplined","Patient","Protective","Observant","Independent","Reserved","Reliable"],"voiceSpeech":["Low calm voice","Measured speech","Rarely raises his voice","Prefers direct statements"],"likesDislikes":["Likes craftsmanship","Likes quiet places","Likes traveling","Likes durable materials","Likes learning new techniques","Dislikes waste","Dislikes reckless destruction","Dislikes unnecessary conflict"],"majorLifeEvents":"Born to Terrax and Leviathans\nAwakened Bone Dragon magic\nBecame a master craftsman\nSettled in the Shifting Sands with Gaius\nCrafted the Bone Dragon Whip for Ife\nBecame a frequent wanderer"}','{"weapons":"Manifested bone blades\nBone spears\nBone shields\nBone gauntlets","strengths":"Extreme durability\nPowerful defense\nRapid regeneration\nVersatile weapon creation\nExcellent battlefield control\nHigh physical strength\nSkilled craftsmanship","weaknesses":"Large constructs require more energy\nRepeated regeneration causes fatigue\nExtreme damage can slow reconstruction\nProtective instincts can be exploited","combatStyle":["Defensive combat","Counterattacking","Close-range combat","Battlefield control","Adaptive weapon creation"],"limitations":["Bone creation consumes energy","Density increases require concentration","Large-scale regeneration is exhausting","Cannot endlessly create massive structures"],"powerSource":["Bone Magic","Earth lineage","Water lineage","Draconic power"],"abilityNotes":"His bone is a living synthesis of Earth minerals and Water-driven regeneration. Broken constructs can pull themselves back together when enough of his magic remains.\n\nRuchika is not missing and does not suffer from memory loss. Those story elements belong to Rahim.","combatProfile":"Ruchika fights like a moving fortress. He absorbs pressure, controls space with bone structures, and changes his weapons according to the opponent.","weaponDetails":"Ruchika normally creates weapons directly from living bone. He can alter their shape, weight, flexibility, and density during combat.","transformations":"True Bone Dragon Form\nPartial Bone Armor","primaryAbilities":"Skeletal Replication\nBone Generation\nBone Manipulation\nDensity Manipulation\nInstant Bone Mending\nBone Weapon Creation\nBone Armor Creation","secondaryAbilities":"Enhanced durability\nEnhanced strength\nStructural awareness\nMineral sensing\nRapid bone regeneration\nHeat-resistant bone constructs","signatureTechniques":"Ivory Fortress\nSkeletal Bloom\nMarrow Forge\nBone Bastion\nIvory Lance\nLiving Arsenal","transformationDetails":"In his true form, Ruchika becomes a massive dragon covered in an ivory exoskeleton. Dark slate-blue skin shows beneath the armor, while translucent water-like membranes stretch between enormous bone wing digits."}','{"allies":"Gaius\nIfe\nTerrax\nLeviathans","rivals":"","enemies":"","mentors":"Terrax — Earth and structural discipline\nLeviathans — Fluidity and regeneration","parents":"Terrax — Father\nLeviathans — Mother","partner":"","children":"","siblings":"Gaius — Brother\nIfe — Sister\nRahim — Brother","worldConnections":"Shifting Sands — Home\nTerrax — Paternal connection\nSunken Dominion — Maternal connection\nUmbral World — Wandering territory","relationshipNotes":"Ruchika lives in the Shifting Sands with Gaius and shares a strong brotherly bond with him. He is especially protective of Ife and personally crafted the Bone Dragon Whip for her. Rahim''s disappearance remains a concern for the family."}','{"tbdFields":"Exact age\nBirth date\nExact birthplace\nExact weight\nDominant hand\nName meaning\nNationality\nRomantic partner\nPermanent enemies","canonLocks":"Ruchika is the Bone Dragon\nMale\nSon of Terrax and Leviathans\nEarth + Water heritage\nBrother of Gaius\nBrother of Ife\nBrother of Rahim\nLives in the Shifting Sands with Gaius\nRuchika is a wanderer\nRuchika is a master craftsman\nRuchika crafted Ife''s Bone Dragon Whip\nRuchika is not missing\nRuchika does not have memory loss\nTrue form uses an ivory bone exoskeleton\nDragon wings have water-like membranes","galleryUrl":"","mediaNotes":"Human and dragon references should preserve the same ivory, midnight blue, slate gray, earth brown, black, and golden amber palette.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7538e2ae-03cd-4c2f-a116-05e51b4fa245/portrait/1790317260638-ruchika-s-character-portrait.png","visualAssets":"Official character portrait — Needed\nFull-body front view — Needed\nBack view — Needed\nLeft view — Needed\nRight view — Needed\nFace reference — Needed\nHair reference — Needed\nOutfit breakdown — Needed\nBone weapon reference — Needed\nTrue Bone Dragon Form — Needed\nCombat reference — Needed\nBone Dragon Whip — Done","productionNotes":"Keep his silhouette tall and grounded. Bone should be modeled separately from skin and clothing so it can emerge, retract, break, and regenerate during animation.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7538e2ae-03cd-4c2f-a116-05e51b4fa245/reference/1790317393231-ruchika-s-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7538e2ae-03cd-4c2f-a116-05e51b4fa245/alternate/1790317539819-ruchika-s-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7538e2ae-03cd-4c2f-a116-05e51b4fa245/portrait/1790317260638-ruchika-s-character-portrait.png',6,1,1,'48066562-cd1c-4b72-8c29-399594efad38','1ec72d01-822b-4992-9434-7772a6b4e474','b17917f0-1e8d-4ecf-b622-61a143f39f32','fc49b3d1-6cee-431a-8881-6a0873d53804','2026-09-25T16:19:45.097434+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('302f42c7-2c06-47de-a5ef-6d2940d026bf','db618e68-0656-4b9b-b308-81e071faf745','Terrax','complete','{"age":"Ancient","era":"Primordial","name":"Terrax","race":"Primordial","alias":"Terrance","gender":"Male","titles":"The Earth Primordial\nThe Earth Dragon\nThe First Stone\nThe Mountain Father\nThe One Who Remembers","subrace":"Earth Primordial","summary":"Terrax is the primordial embodiment of Earth and the living foundation of the physical world. His primordial truth, the Telluric Verity, embodies permanence, resilience, gravity, weight, and the memory held within the earth. He rules his own land called Terrax and considers the Stone Mountains a personal sanctuary where he can relax away from his responsibilities.","heritage":"Indian","homeland":"Terrax","pronouns":"He/Him","birthDate":"TBD","nicknames":"","occupation":"Primordial embodiment of Earth","affiliation":"Terrax","apparentAge":"Adult","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TERR-aks","currentResidence":"Terrax","elementalHeritage":"Primordial Earth"}','{"build":["Tall","Muscular","Broad-shouldered"],"nails":["Natural"],"eyeHex":["#8A6036"],"height":"TBD","makeup":"","weight":"TBD","hairHex":["#11100F"],"skinHex":["#70472F"],"eyeColor":["Earthy amber-brown"],"grooming":"Well-kept with a rugged natural appearance","skinTone":["Deep warm brown"],"wardrobe":"Layered robes\nLoose trousers\nDraped mantle\nLeather sandals\nOrnamental belts","hairColor":["Black"],"hairStyle":"Long layered hair worn loose and partially pulled back","accessories":"Ornate earrings\nLayered necklaces\nStone rings\nMetal bracers\nDecorative belt\nGemstone ornaments","faceDetails":["Strong angular jaw","Defined cheekbones","Heavy brows","Straight nose"],"hairTexture":["Thick","Wavy"],"colorPalette":"Earth brown #70472F\nObsidian #171512\nForest green #263B2A\nAntique gold #A77A36\nStone gray #716B60","dominantHand":"TBD","outfitColors":"Forest green\nBlack\nEarth brown\nAntique gold\nStone gray","alternateForm":["Mountain-sized Earth Dragon"],"clothingStyle":"Ancient Indian-inspired fantasy clothing suited to the Umbra World''s 500–1300 AD-inspired aesthetic. His clothing should feel ancient, earthy, regal, practical, and connected to stone rather than resembling modern fashion.","appearanceNotes":"Terrance is Terrax''s humanoid form and should retain the same Indian appearance, long black hair, warm brown skin, earthy palette, gold accents, and ancient grounded presence established in his visual references. His design should communicate immense strength without making him look excessively armored.","outfitMaterials":["Woven cloth","Leather","Metal","Stone","Gemstone"],"postureMovement":["Grounded stance","Heavy deliberate movement","Relaxed posture"],"signatureOutfit":"Layered Indian-inspired fantasy robes with dark green draping, black and earth-brown fabrics, antique-gold embroidery, loose trousers, leather sandals, belts, jewelry, and stone-set ornaments.","distinguishingFeatures":["Golden earth markings","Forehead sigil","Long black hair","Ornate earrings","Earth-toned jewelry"]}','{"fears":["TBD"],"goals":["Maintain the Telluric Verity","Protect Terrax","Preserve the physical world"],"beliefs":["Everything has weight","The earth remembers","Permanence has value","Resilience comes through endurance"],"culture":["Primordial","Indian-inspired"],"lineage":"Primordial embodiment of Earth","storyArc":"TBD","backstory":"Terrax is an ancient Primordial who embodies Earth itself rather than merely ruling the earth element. His existence is tied to the Telluric Verity, the cosmic truth of permanence, resilience, gravity, weight, and physical memory. He personally rules the land called Terrax while allowing unrelated human and nonhuman civilizations elsewhere to govern themselves.","childhood":"TBD","lifestyle":["Retreats to the Stone Mountains","Spends time with his children","Smokes to relax","Enjoys quiet natural spaces"],"storyRole":"Terrax serves as the Primordial embodiment of Earth and father of Ruchicka, Gaius, and Shailara. His existence establishes the metaphysical foundation of earth, stone, gravity, permanence, and physical memory within the Umbra World.","birthplace":"TBD","psychology":["Extremely patient","Values permanence","Difficult to provoke","Comfortable with silence"],"motivations":["Preserve the earth","Protect his children","Maintain natural stability"],"personality":["Calm","Grounded","Patient","Relaxed","Stoic","Independent"],"voiceSpeech":["Deep voice","Measured speech","Few unnecessary words","Heavy relaxed tone"],"likesDislikes":["Likes smoking","Likes mountains","Likes peace and quiet","Likes relaxing","Dislikes unnecessary disturbance"],"majorLifeEvents":"Became the living embodiment of Earth\nFathered Ruchicka with Shuǐmǔ Lánhuá\nFathered Gaius with Aetheros\nFathered Shailara with a Sylvani elf"}','{"weapons":"","strengths":"Immense physical strength\nExtreme durability\nPrimordial resilience\nGravity control\nEarth control\nMassive scale","weaknesses":"TBD","combatStyle":["Heavy","Grounded","Overwhelming force","Defensive","Terrain control"],"limitations":["TBD"],"powerSource":["Telluric Verity","Primordial Earth"],"abilityNotes":"The Telluric Verity is not ordinary earth magic. It is Terrax''s primordial truth governing permanence, resilience, gravity, physical weight, and the memory of the earth. Terrax is the living embodiment of Earth rather than a Dragon Primal who merely controls it.\n\nTerrax should not be treated as the political ruler of every civilization located on land. Ironspire Hold and Eldoria are independent of his rule. His direct territory is Terrax, while the Stone Mountains function primarily as his sanctuary.","combatProfile":"Terrax fights with the overwhelming weight and stability of the earth itself. His combat style favors immense force, resilience, gravity, terrain manipulation, and attacks capable of reshaping the battlefield. His movements may appear slow or deliberate compared with faster Primordials, but each action carries enormous physical weight.","weaponDetails":"No established signature weapon.","transformations":"Earth Dragon Form\nHuman Form","primaryAbilities":"Earth manipulation\nStone manipulation\nGravity manipulation\nTectonic manipulation\nTelluric Verity","secondaryAbilities":"Extreme resilience\nEarth sensing\nGeological awareness\nMountain-scale transformation","signatureTechniques":"Telluric Verity","transformationDetails":"Terrax can manifest as Terrance, his humanoid form, or reveal his true Earth Dragon form. His dragon form is mountain-sized, with colossal rocky scales resembling cliffs and mountain formations. His body should appear ancient enough that vegetation, moss, stone, and geological features can naturally form across portions of his scales."}','{"allies":"","rivals":"Ignis","enemies":"","mentors":"","parents":"","partner":"TBD","children":"Ruchicka — Oldest child and Bone Dragon\nGaius — Sand Dragon\nShailara — Youngest child and half-Sylvani Stone Dragon","siblings":"","worldConnections":"Shuǐmǔ Lánhuá — Mother of Ruchicka\nAetheros — Mother of Gaius\nEldoria — Homeland of Shailara''s Sylvani family\nStone Mountains — Personal sanctuary\nHeavy Grumble — Devoted human followers\nIronspire Hold — Independent Duroc homeland","relationshipNotes":"Ruchicka is Terrax''s oldest child with Shuǐmǔ Lánhuá and lives primarily with Terrax while maintaining ties to his mother''s water domain. Gaius is Terrax''s child with Aetheros and lives with his father while maintaining ties to his mother''s air domain. Shailara is Terrax''s youngest child, born to a Sylvani elf; she lives with Terrax while remaining connected to her mother''s people in Eldoria."}','{"tbdFields":"Birth date\nExact age\nExact height\nExact weight\nDominant hand\nBirthplace\nName meaning\nNationality\nFormal partner status\nNamed allies\nNamed rivals\nNamed enemies\nNamed mentors\nSpecific weaknesses\nSpecific power limitations\nStory arc","canonLocks":"Terrax is male\nTerrax is Indian\nTerrax is the Primordial embodiment of Earth\nTerrax is not merely a Dragon Primal\nHis primordial truth is the Telluric Verity\nHis humanoid form is called Terrance\nRuchicka is his oldest child\nGaius is his Sand Dragon child\nShailara is his youngest child\nShailara is half Sylvani elf\nTerrax directly rules the land called Terrax\nStone Mountains is Terrax''s sanctuary\nTerrax is a stoner\nThe Heavy Grumble are devoted human followers\nIronspire Hold is independently governed\nEldoria is within Aethelgarud\nEldoria is the Sylvani homeland","galleryUrl":"","mediaNotes":"Existing artwork establishes both Terrance''s human appearance and Terrax''s colossal Earth Dragon form. The completed visual production sheet should be treated as the main design reference for future artwork.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/302f42c7-2c06-47de-a5ef-6d2940d026bf/portrait/1790318633853-terrax-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Done\nFace Reference — Done\nEye Reference — Needed\nHair Reference — Needed\nOutfit Breakdown — Done\nExpression Sheet — Done\nCombat Reference — Needed","productionNotes":"Use the established production sheet as Terrax''s primary visual canon. Future human artwork should preserve his Indian features, warm brown skin, long black hair, powerful build, earth markings, dark green and earth-toned clothing, antique-gold detailing, jewelry, and ancient fantasy aesthetic. His dragon form must remain colossal, rocky, mountain-like, winged, and visibly connected to the Telluric Verity.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/302f42c7-2c06-47de-a5ef-6d2940d026bf/reference/1790318701593-terrax-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/302f42c7-2c06-47de-a5ef-6d2940d026bf/alternate/1790318762884-terrax-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/302f42c7-2c06-47de-a5ef-6d2940d026bf/portrait/1790318633853-terrax-character-portrait.png',6,1,1,'53d924ac-f33c-491b-a246-240d886c2de5','f0c6ce62-f547-4fc2-8765-6a9f8bebc590','0ba48458-c018-47e8-bfc0-bcfcd31aa531','cc24abab-518b-4ef0-8cbe-dbea119ee873','2026-09-25T16:18:09.187254+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('c48e35c9-e98d-414c-afb7-ae85f99eb649','db618e68-0656-4b9b-b308-81e071faf745','Atherous','complete','{"age":"Primordial","era":"Primordial Era","name":"Atherous","race":"Primordial","alias":"The Veiled Whisper","gender":"Female","titles":"The Veiled Whisper\nThe Eternal Horizon\nLiving Embodiment of Air","subrace":"God-Prime","summary":"Atherous is the primordial living embodiment of air. She does not simply rule wind or possess air magic; air itself is her elemental existence. Her authority encompasses wind, atmosphere, sound, vibration, frequency, vacuum, storms, flight, motion, and the unseen pathways connecting the world. Her primordial truth is Veritas Volans, the Law of Eternal Change.","heritage":"Caucasian","homeland":"Veylora","pronouns":"She / Her","birthDate":"TBD","nicknames":"","occupation":"Primordial Sovereign","affiliation":"Veylora","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Veylora","elementalHeritage":"Primordial Air"}','{"build":["Tall","Elegant","Slender"],"nails":["Pale silver"],"eyeHex":["#BFD8EA"],"height":"TBD","makeup":["Subtle cool-toned makeup"],"weight":"TBD","hairHex":["#E8EAF0","#F4F5F7"],"skinHex":["#F2E8E5"],"eyeColor":["Silver-blue"],"grooming":"Immaculate and ethereal","skinTone":["Fair porcelain"],"wardrobe":"Flowing ceremonial gowns\nAir-themed divine garments","hairColor":["Silver-white"],"hairStyle":"Extremely long flowing silver-white hair","accessories":"Silver headpiece\nCrystal ornaments\nSilver jewelry","faceDetails":["Elegant facial structure","High cheekbones","Delicate features"],"hairTexture":["Silky","Flowing"],"colorPalette":"Cloud white #F4F5F7\nSilver #C7CCD6\nFrost blue #BFD8EA\nSky blue #AFCDE3\nMoonlight pearl #E7E5ED","dominantHand":"TBD","outfitColors":"White\nSilver\nFrost blue","alternateForm":["Primordial Air Dragon"],"clothingStyle":"Ethereal fantasy regalia built around flowing layers, silver ornamentation, and lightweight materials that constantly react to surrounding air currents.","appearanceNotes":"Atherous should always appear exceptionally beautiful, ethereal, and nearly weightless. Her hair and clothing should appear affected by invisible currents even while she stands still. Her established visual identity is white, silver, frost blue, and luminous atmospheric effects.","outfitMaterials":["Flowing fabric","Translucent fabric","Silver ornamentation","Crystal accents"],"postureMovement":["Graceful","Weightless","Fluid"],"signatureOutfit":"A flowing white-and-silver fantasy gown with crystalline detailing, layered translucent fabrics, and long wind-swept elements. The silhouette remains elegant and otherworldly while fitting the fantasy identity of the Umbra World.","distinguishingFeatures":["Silver-white hair","Silver-blue eyes","Ethereal beauty","Wind-swept silhouette","White atmospheric aura"]}','{"fears":["TBD"],"goals":["Uphold Veritas Volans"],"beliefs":["Nothing should be bound","Change is necessary","Air carries truth"],"culture":["Veyloran"],"lineage":"Primordial embodiment of Air","storyArc":"TBD","backstory":"Atherous is one of the primordial elemental beings of the Umbra World and embodies air itself rather than merely governing it. Her existence encompasses the atmosphere and its movement, allowing her presence to extend wherever air exists. Her primordial truth, Veritas Volans, represents freedom, motion, transition, and eternal change.","childhood":"TBD","lifestyle":["Exists throughout her atmospheric domain","Moves freely through Veylora"],"storyRole":"Atherous serves as the primordial embodiment of Air and sovereign presence of Veylora. Through her, the Umbra World''s wind, atmosphere, sound, vibration, vacuum, and atmospheric motion are connected to a single primordial source.","birthplace":"TBD","psychology":["Values freedom","Rejects stagnation","Embraces change"],"motivations":["Preserve freedom","Maintain atmospheric balance"],"personality":["Elusive","Free-spirited","Graceful","Calm","Independent"],"voiceSpeech":["Soft-spoken","Ethereal","Controlled"],"likesDislikes":["Values freedom","Values movement","Dislikes confinement"],"majorLifeEvents":"Became mother of Ezra with Ignis\nBecame mother of Gaius with Terrax"}','{"weapons":"Echoing Truth — Sonic Blade","strengths":"Extreme speed\nAtmospheric control\nLong-range attacks\nSound manipulation\nFrequency control\nAerial mobility\nVacuum creation","weaknesses":"TBD","combatStyle":["Extreme-speed combat","Sonic swordsmanship","Aerial combat","Precision strikes","Battlefield control"],"limitations":["TBD"],"powerSource":["Primordial Air","Veritas Volans","Veiled Whisper"],"abilityNotes":"The Veiled Whisper governs vibration and frequency rather than simple wind manipulation. Atherous can weaponize sound, create vacuums, alter atmospheric pressure, transmit whispers through air, and form sonic cutting forces. Her magic may sound like sharp whistles, cracking whips, or countless distant voices.\n\nAtherous must not be described as merely an Air Dragon who rules air. Her dragon form is a manifestation of her primordial nature; she is the living embodiment of Air itself.","combatProfile":"Atherous specializes in overwhelming speed, aerial mobility, atmospheric control, and precision attacks. Void Sky — The Eternal Horizon allows her movement to resemble teleportation as she slides through the horizon, while residual currents can remain behind as damaging after-images. Horizon Slice allows her to pass an opponent before the displaced air produces the actual cut.","weaponDetails":"Echoing Truth is Atherous''s signature Sonic Blade. It channels her authority over sound, vibration, frequency, and air into a sword capable of producing devastating frequency-based cuts. Its design uses silver-white and frost-blue atmospheric energy consistent with Atherous''s established visual identity.","transformations":"Primordial Air Dragon Form","primaryAbilities":"Atmospheric Command\nWind Manipulation\nStorm Manipulation\nSound Manipulation\nFrequency Manipulation\nVibration Manipulation\nVacuum Creation\nAtmospheric Pressure Control","secondaryAbilities":"Flight\nSonic Blades\nSound-Sight\nLong-Distance Whispering\nAir Removal\nExtreme-Speed Movement","signatureTechniques":"Void Sky — The Eternal Horizon\nThe Severing Current\nHorizon Slice\nThe Echoing Truth\nVacuum — The Absence of Breath","transformationDetails":"Atherous can manifest as a colossal silver-white air dragon with immense wings, an elongated draconic silhouette, luminous pale eyes, and atmospheric energy flowing around her body. The form should retain the same silver, white, and frost-blue palette as her human appearance."}','{"allies":"Ignis — Father of Ezra\nTerrax — Father of Gaius","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"Ezra — Son with Ignis; Lightning Dragon\nGaius — Son with Terrax; Sand Dragon","siblings":"","worldConnections":"Veylora — Primordial domain\nIgnis — Ezra''s father\nTerrax — Gaius''s father\nEzra — Lightning Dragon son\nGaius — Sand Dragon son","relationshipNotes":"Ezra is the son of Atherous and Ignis and lives primarily with Atherous while retaining a sovereign connection to his father''s domain. Gaius is the son of Atherous and Terrax and lives primarily with Terrax while retaining a sovereign connection to his mother''s domain."}','{"tbdFields":"Pronunciation\nName meaning\nBirth date\nExact age\nApparent age\nExact height\nExact weight\nDominant hand\nNationality\nBirthplace\nChildhood\nStory arc\nSpecific fears\nAbility weaknesses\nAbility limitations","canonLocks":"Atherous is female\nAtherous is Caucasian\nAtherous is a Primordial\nAtherous is the living embodiment of Air\nAtherous is not merely an Air Dragon ruler\nAtherous has silver hair\nAtherous is mother of Ezra\nIgnis is Ezra''s father\nAtherous is mother of Gaius\nTerrax is Gaius''s father\nEzra is the Lightning Dragon\nGaius is the Sand Dragon\nEzra lives primarily with Atherous\nGaius lives primarily with Terrax\nVeritas Volans is Atherous''s primordial truth\nThe Veiled Whisper governs vibration and frequency\nVoid Sky — The Eternal Horizon is an Atherous power\nEchoing Truth is Atherous''s Sonic Blade","galleryUrl":"","mediaNotes":"Existing visual references establish Atherous''s human form, Primordial Air Dragon form, production sheet, and Echoing Truth Sonic Blade. These designs should be treated as the visual continuity reference for future artwork.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/portrait/1790319732526-aetheros-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nWeapon Reference — Done\nExpression Sheet — Done\nCombat Reference — Done","productionNotes":"Maintain Atherous''s established anime/fantasy appearance across every future asset. Her human form uses long silver-white hair, fair porcelain skin, silver-blue eyes, an elegant slender build, flowing white-and-silver clothing, and frost-blue atmospheric effects. Her dragon form remains silver-white and luminous. Echoing Truth must retain its established silver-white sonic and atmospheric design.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/reference/1790319737660-aetheros-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/alternate/1790319744447-aetheros-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/portrait/1790319732526-aetheros-character-portrait.png',6,1,1,'fd4462c1-d940-4eb8-8105-5ff2b323bc99','f0c6ce62-f547-4fc2-8765-6a9f8bebc590','efcdcdc6-0a8e-4713-8e49-fce93c606887','b32427ed-0baf-457b-8c84-b0266dd31c76','2026-09-25T16:17:16.362719+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('56793a81-e4e6-48b9-a18a-28f6783ead66','db618e68-0656-4b9b-b308-81e071faf745','Ignis','complete','{"age":"Ancient","era":"Primordial Era","name":"Ignis","race":"Primordial","alias":"","gender":"Male","titles":"Primordial of Fire\nThe Living Flame\nThe First Burning\nThe Sovereign Pyre\nThe Fire Dragon","subrace":"Primordial Dragon","summary":"Ignis is the primordial living embodiment of Fire and sovereign of Ignis Peaks. His dragon form is the physical manifestation of his primordial nature rather than the source of his authority. Ancient, knowledgeable, noble, cocky, and intensely competitive, Ignis is fascinated by strength and constantly seeks opponents capable of giving him exhilarating battles. He fiercely protects his realm and people while encouraging strength through challenge.","heritage":"Primordial","homeland":"Ignis Peaks","pronouns":"He/Him","birthDate":"TBD","nicknames":"","occupation":"Sovereign of Ignis Peaks","affiliation":"Ignis Peaks","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"Fire","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"IG-nis","currentResidence":"Moltenmaw Caverns, Ignis Peaks","elementalHeritage":"Primordial Fire"}','{"build":["Tall","Muscular","Powerful"],"nails":"","eyeHex":["#C9D1D4"],"height":"7 ft","makeup":"","weight":"TBD","hairHex":["#090909","#E94B16"],"skinHex":["#5A2F24"],"eyeColor":["Luminous winter grey"],"grooming":"Immaculately maintained goatee and locs","skinTone":["Deep rich mahogany brown"],"wardrobe":"Regal battle attire\nPrimordial ceremonial attire","hairColor":["Black","Fire-colored tips"],"hairStyle":"Long black locs with flame-like tips","accessories":"Gold jewelry\nDraconic ornamentation","faceDetails":["Strong masculine features","Defined jawline","Serious expression"],"hairTexture":["Locs"],"colorPalette":"Obsidian black\nDark crimson\nMolten orange\nEmber red\nAntique gold","dominantHand":"TBD","outfitColors":"Obsidian black\nDark crimson\nMolten orange\nAntique gold","alternateForm":["Primordial Fire Dragon"],"clothingStyle":"Ancient fantasy warrior nobility with volcanic and draconic motifs appropriate to the 500–1300 AD-inspired Umbra World aesthetic.","appearanceNotes":"Ignis must consistently appear as a towering Black man with deep mahogany skin, luminous winter-grey eyes, long black locs with fire-like tips, a neat goatee, and a powerful muscular build. His expression is usually serious or mildly disinterested because of his nonchalant personality. His visual presence should communicate restrained primordial power rather than constant aggression.","outfitMaterials":["Dark leather","Heavy woven fabric","Metal ornamentation"],"postureMovement":["Relaxed confidence","Commanding stance","Unhurried movement"],"signatureOutfit":"Regal black fantasy attire suited to an ancient warrior-sovereign, accented with dark crimson, molten-fire details, and restrained gold ornamentation. The silhouette is imposing without appearing overly ceremonial.","distinguishingFeatures":["Luminous winter-grey eyes","Flame-tipped locs","Very neat goatee","Towering height"]}','{"fears":["TBD"],"goals":["Remain worthy of his strength","Protect his primordial domain","Challenge powerful beings","Battle Rahim again"],"beliefs":["Strength must be tested","Defeat can create growth","Power should be proven","Challenges reveal character","Strength deserves respect"],"culture":["Ignis Peaks","Primordial culture","Warrior culture"],"lineage":"Primordial living embodiment of Fire","storyArc":"A major emotional thread surrounding Ignis is Rahim''s disappearance. Rahim was not merely his eldest son but one of the few beings capable of providing the kind of prolonged, exhilarating battle Ignis craves. Ignis continues challenging his children and other powerful beings, but the possibility of fighting Rahim again remains uniquely important to him.","backstory":"Ignis is an ancient primordial whose existence is intrinsically connected to Fire itself. He rules Ignis Peaks from Moltenmaw Caverns and protects the civilizations that exist within his primordial domain. His fascination with strength shaped both his rule and his relationship with his children. His battles with his eldest son Rahim were among the most exhilarating fights of his existence, making Rahim''s disappearance a deeply significant absence.","childhood":"TBD","lifestyle":["Rules from Moltenmaw Caverns","Hosts combat competitions","Trains through battle","Challenges his children","Protects Ignis Peaks"],"storyRole":"Ignis functions as the primordial embodiment of Fire, sovereign protector of Ignis Peaks, and father of several powerful elemental dragons. His overwhelming power contrasts with his casual personality and love of competition. His relationship with his children reveals both his warrior philosophy and his capacity for familial pride.","birthplace":"TBD","psychology":["Craves worthy competition","Thrives on escalation","Respects earned strength","Enjoys being challenged","Misses battling Rahim","Hides wisdom beneath bravado"],"motivations":["Experience worthy battles","Protect Ignis Peaks","Test his strength","Strengthen his children","Find exhilarating opponents"],"personality":["Nonchalant","Cocky","Competitive","Battle-loving","Noble","Knowledgeable","Protective","Self-assured","Playful in combat","Strength-driven"],"voiceSpeech":["Deep voice","Calm delivery","Understated trash talk","Short challenges","Rarely raises his voice"],"likesDislikes":["Likes powerful opponents","Likes difficult battles","Likes competition","Likes courageous challengers","Likes testing new techniques","Dislikes false strength","Dislikes cowardice","Dislikes unearned arrogance"],"majorLifeEvents":"Became sovereign of Ignis Peaks\nFathered Rahim with Leviathans\nFathered Ife with Leviathans\nFathered Ezra with Aetheros\nFathered AshóNodia with Hecate\nFrequently battled Rahim\nRahim disappeared\nContinued family combat competitions"}','{"weapons":"","strengths":"Primordial power\nExtreme physical strength\nAncient combat experience\nFire mastery\nExceptional durability\nBattle intelligence\nDraconic power","weaknesses":"TBD","combatStyle":["Aggressive escalation","Close-quarters combat","Draconic combat","Power contests","Adaptive combat","High-output elemental combat"],"limitations":["TBD"],"powerSource":["Primordial Fire","Living embodiment of Fire"],"abilityNotes":"Ignis''s elemental authority originates from his primordial identity. Fire is not simply a learned magical discipline for him. His knowledge and combat experience are ancient, although his competitive personality often causes others to overlook his intelligence.\n\nIgnis must never be described merely as a dragon who controls fire. He is the primordial living embodiment of Fire; the Fire Dragon is one manifestation of that nature.","combatProfile":"Ignis fights because he genuinely enjoys testing strength. Against weaker opponents he may remain relaxed or deliberately limit himself. A powerful opponent causes him to progressively escalate, seeking the moment both combatants are forced to reveal everything they possess. He does not spare his children during their agreed combat competitions simply because they are family; their ability to challenge him is a source of pride.","weaponDetails":"TBD","transformations":"Primordial Fire Dragon Form","primaryAbilities":"Primordial fire manipulation\nFire generation\nHeat manipulation\nMagma manipulation\nDragon transformation\nPrimordial physical strength","secondaryAbilities":"Extreme fire resistance\nExtreme heat resistance\nDraconic flight\nPrimordial durability\nEnhanced senses","signatureTechniques":"TBD","transformationDetails":"Ignis transforms into an immense black dragon whose obsidian scales contain dim dark-crimson light between their seams. Molten magma appears to leak between portions of his scales, making his body resemble a living volcanic formation. His eyes burn with sun-like intensity. This form must remain predominantly black rather than becoming a conventional red fire dragon."}','{"allies":"","rivals":"Rahim — Son and treasured combat rival","enemies":"","mentors":"","parents":"","partner":"TBD","children":"Rahim — Eldest son; Blood Dragon\nIfe — Daughter; Steam Dragon\nEzra — Son; Lightning Dragon\nAshóNodia — Son; Ash Dragon","siblings":"","worldConnections":"Ignis Peaks — Primordial domain\nMoltenmaw Caverns — Primary residence\nLeviathans — Mother of Rahim and Ife\nAetheros — Mother of Ezra\nHecate — Mother of AshóNodia\nCinderkin Elves — Protected people\nOrcs — Protected people\nGoblins — Protected people\nDragonborn — Protected people\nLizardfolk — Protected people\nFireborn — Protected beings","relationshipNotes":"Ignis expresses much of his affection through competition, training, and combat. Rahim, his eldest son with Leviathans, became an especially important combat partner because their battles could reach extraordinary levels of power. Ife also shares much of Ignis''s temperament and resides with him. Ezra primarily resides with his mother Aetheros but maintains a connection to his father''s domain. AshóNodia is Ignis''s son with Hecate and embodies Ash rather than conventional fire."}','{"tbdFields":"Birth date\nApparent human age\nWeight\nDominant hand\nNationality\nBirthplace\nExact origin of primordial existence\nNamed signature techniques\nPersonal weapons\nSpecific weaknesses\nSpecific power limitations\nCurrent romantic status","canonLocks":"Ignis is male\nIgnis uses he/him pronouns\nIgnis is the primordial embodiment of Fire\nIgnis is not merely a dragon ruling fire\nIgnis rules Ignis Peaks\nIgnis resides in Moltenmaw Caverns\nHuman form is approximately 7 ft tall\nHuman skin is deep mahogany brown\nEyes are luminous winter grey\nHair is long black locs with fire-like tips\nIgnis has a neat goatee\nDragon form is predominantly black\nDragon scale seams glow dark crimson\nDragon scales appear to leak magma\nDragon eyes resemble the sun\nRahim is his eldest son\nRahim is the Blood Dragon\nIfe is his daughter\nIfe is the Steam Dragon\nEzra is his son\nEzra is the Lightning Dragon\nAshóNodia is his son\nAshóNodia is the Ash Dragon\nLeviathans is the mother of Rahim and Ife\nAetheros is the mother of Ezra\nHecate is the mother of AshóNodia\nRahim is missing","galleryUrl":"","mediaNotes":"Maintain strict visual continuity with the completed Ignis portrait, dragon design, and production sheet. Future images should use the same anime/fantasy character identity rather than redesigning him.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/56793a81-e4e6-48b9-a18a-28f6783ead66/portrait/1790318177179-ignis-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nExpression Sheet — Done\nCombat Reference — Needed","productionNotes":"Use the established production sheet as Ignis''s primary visual canon reference. Human and dragon artwork must preserve his established proportions, palette, facial identity, hair, and primordial aesthetic. His dragon form must remain an immense obsidian-black dragon with dark-crimson glowing scale seams, magma leakage, and sun-like eyes.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/56793a81-e4e6-48b9-a18a-28f6783ead66/reference/1790318348588-ignis-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/56793a81-e4e6-48b9-a18a-28f6783ead66/alternate/1790318419544-ignis-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/56793a81-e4e6-48b9-a18a-28f6783ead66/portrait/1790318177179-ignis-character-portrait.png',6,1,1,'97d4dc51-d1bf-4f80-9e77-3955ba9dad35','f0c6ce62-f547-4fc2-8765-6a9f8bebc590','406ddfbf-feab-4b20-9026-bd74b716fbda','758ec32c-b7b2-441a-bc67-15bd2cdaae41','2026-09-25T08:17:18.986171+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('b2d998c0-1754-4a6a-af91-281d65ded816','db618e68-0656-4b9b-b308-81e071faf745','Shuǐmǔ Lánhuá','complete','{"age":"Unknown","era":"Ancient","name":"Shuǐmǔ Lánhuá","race":"Primordial","alias":"Lady Lánhuá","gender":"Female","titles":"Shuǐmǔ Tiān Hòu\nHeavenly Empress, Mother of All Waters\nThe Splendid Orchid\nMother of All Waters","subrace":"Living Embodiment of Water","summary":"Shuǐmǔ Lánhuá is the ancient Primordial and living embodiment of Water itself. She does not merely command water; oceans, seas, ice, rain, mist, currents, and other natural forms of water are expressions of her primordial existence. Known among mortals as Lady Lánhuá, she rules the Sunken Domain, which encompasses the world''s waters rather than existing within Aethelgard. She is the mother of Rahim, Ife, and Ruchika.","heritage":"Asian","homeland":"Sunken Domain","pronouns":"She/Her","birthDate":"TBD","nicknames":"","occupation":"Primordial Sovereign of Water","affiliation":"Sunken Domain","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"The Splendid Orchid, Mother of Waters","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Sunken Domain","elementalHeritage":"Primordial Water"}','{"build":["Slender","Graceful","Regal"],"nails":["TBD"],"eyeHex":["TBD"],"height":"TBD","makeup":["Subtle","Elegant"],"weight":"TBD","hairHex":["#090D18"],"skinHex":["TBD"],"eyeColor":["Ocean blue"],"grooming":"Immaculate and imperial.","skinTone":["Fair"],"wardrobe":"Layered ceremonial robes\nImperial water-themed gowns\nFlowing silk garments","hairColor":["Black"],"hairStyle":"Very long black hair styled with ornate water-themed hairpieces.","accessories":"Ice orchid hair ornaments\nOrnate hairpins\nWater-drop earrings\nDragon-scale necklace\nWater orb pendant\nJade ornaments","faceDetails":["Elegant features","Regal expression","Refined facial structure"],"hairTexture":["Straight","Silky"],"colorPalette":"Midnight blue #071A33\nDeep teal #07566B\nSeafoam #67C8C2\nTurquoise #46CFE0\nSilver #C8D5DF\nPearl white #EEF3F4","dominantHand":"TBD","outfitColors":"Midnight blue\nDeep teal\nTurquoise\nSilver\nPearl white","alternateForm":["Abyssal Leviathan","Eastern-style sea dragon"],"clothingStyle":"Regal 500–1300 AD-inspired Asian fantasy clothing with flowing silhouettes, layered silks, wave motifs, and refined ornamentation.","appearanceNotes":"Her human design should feel ancient, serene, elegant, and unmistakably connected to the ocean. Her clothing and hair should appear to move with subtle underwater fluidity even on land. Maintain the established midnight-blue, teal, turquoise, silver, and pearl palette across all artwork.","outfitMaterials":["Silk","Translucent silk","Fine embroidery"],"postureMovement":["Poised","Fluid","Controlled"],"signatureOutfit":"Flowing multi-layered imperial robes inspired by 500–1300 AD Asian dress, combining midnight blue, deep teal, silver, and translucent water-like layers. Fine wave and orchid motifs decorate the fabric.","distinguishingFeatures":["Ocean-blue eyes","Very long black hair","Water-themed hair ornaments","Regal presence"]}','{"fears":["TBD"],"goals":["Protect the Sunken Domain","Preserve aquatic life","Safeguard her family"],"beliefs":["Water sustains life","Water must remain balanced"],"culture":["Ancient aquatic court","Asian-inspired imperial aesthetic"],"lineage":"Primordial embodiment of Water.","storyArc":"Her larger story arc remains TBD. Rahim''s disappearance creates an unresolved thread within her family, while Ife and Ruchika maintain connections to her domain despite residing with their fathers.","backstory":"Lánhuá is one of the ancient Primordials and the living embodiment of Water. Her sovereignty is not limited to a single ocean or continent; the Sunken Domain encompasses the waters of the world. Her unions with Ignis produced Rahim and Ife, while her union with Terrax produced Ruchika. Although Ife and Ruchika reside with their fathers, they remain connected to their mother''s domain and visit her. Rahim is currently lost, and his absence remains unresolved.","childhood":"TBD","lifestyle":["Rules the Sunken Domain","Oversees the waters of the world","Receives visits from her children"],"storyRole":"Lánhuá serves as the primordial embodiment of Water and sovereign of the Sunken Domain. Her existence connects the oceans, aquatic civilizations, and several elemental bloodlines through her children Rahim, Ife, and Ruchika.","birthplace":"TBD","psychology":["Emotionally restrained","Deeply maternal","Patient observer","Terrifying when enraged"],"motivations":["Protect her children","Preserve the waters","Maintain natural balance"],"personality":["Patient","Calm","Soft-spoken","Graceful","Observant","Maternal","Protective","Formidable"],"voiceSpeech":["Soft-spoken","Measured","Regal","Controlled"],"likesDislikes":["TBD"],"majorLifeEvents":"Union with Ignis\nBirth of Rahim\nBirth of Ife\nUnion with Terrax\nBirth of Ruchika\nRahim disappeared\nIfe resides with Ignis\nRuchika resides with Terrax"}','{"weapons":"","strengths":"Elemental fluidity\nExtreme water pressure\nEnvironmental control\nAquatic dominion\nAncient primordial power","weaknesses":"TBD","combatStyle":["Fluid","Defensive","Environmental","Pressure-based","Large-scale elemental control"],"limitations":["TBD"],"powerSource":["Primordial Water","Living embodiment of Water"],"abilityNotes":"Her authority over water comes from being its primordial embodiment, not from conventional learned water magic. Exact limits and interactions with other Primordials remain TBD.\n\nDo not classify Lánhuá as a Dragon Primal who merely rules water. She is a Primordial and the living embodiment of Water itself.","combatProfile":"Lánhuá fights as an elemental force rather than a conventional warrior. She changes water between liquid, ice, mist, and highly compressed states while manipulating currents, pressure, and surrounding moisture. Her movements remain controlled and graceful until extreme anger causes her power to become devastatingly violent.","weaponDetails":"","transformations":"Human Form\nAbyssal Leviathan Form","primaryAbilities":"Absolute water manipulation\nPhase manipulation\nHydrostatic pressure manipulation\nIce manipulation\nMist manipulation\nRain manipulation\nCurrent manipulation\nAbyssal command","secondaryAbilities":"Water compression\nTemperature manipulation\nAquatic telepathy\nSea-life command\nAtmospheric moisture manipulation","signatureTechniques":"TBD","transformationDetails":"Lánhuá can manifest as a colossal Eastern-style aquatic dragon or sea serpent. Her elongated body carries iridescent midnight-blue, teal, and seafoam scales with a flowing bioluminescent mane. Rather than conventional leathery wings, her established dragon design can manifest immense wings formed from compressed water, mist, and atmospheric moisture."}','{"allies":"TBD","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"Rahim — Son; Blood Dragon; child with Ignis; currently lost\nIfe — Daughter; Steam Dragon; child with Ignis; resides with her father and visits Lánhuá\nRuchika — Son; Bone Dragon; child with Terrax; resides with his father and visits Lánhuá","siblings":"","worldConnections":"Ignis — Father of Rahim and Ife\nTerrax — Father of Ruchika\nSunken Domain — Her primordial realm\nWorld waters — Her elemental existence","relationshipNotes":"Lánhuá is the mother of Rahim, Ife, and Ruchika. Rahim and Ife are her children with Ignis, while Ruchika is her child with Terrax. Ife and Ruchika live with their fathers but retain a connection and form of sovereignty within their mother''s waters and continue to visit her. Rahim remains lost; his established disappearance and story should not be overwritten."}','{"tbdFields":"Birth date\nBirthplace\nApparent age\nHeight\nWeight\nDominant hand\nNationality\nExact weaknesses\nExact power limitations\nFormal signature techniques\nPartner status\nFull story arc\nExact sovereignty structure of her children","canonLocks":"Name: Shuǐmǔ Lánhuá\nHuman title: Lady Lánhuá\nDivine title: Shuǐmǔ Tiān Hòu\nFemale\nAsian heritage\nPrimordial\nLiving embodiment of Water\nRules the Sunken Domain\nSunken Domain encompasses the world''s waters\nSunken Domain is not within Aethelgard\nMother of Rahim\nMother of Ife\nMother of Ruchika\nIgnis is father of Rahim and Ife\nTerrax is father of Ruchika\nIfe is the Steam Dragon\nRuchika is the Bone Dragon\nRahim is the Blood Dragon\nRahim is currently lost\nIfe lives with her father\nRuchika lives with his father\nIfe and Ruchika visit their mother\nTrue form is an Eastern-style aquatic leviathan","galleryUrl":"","mediaNotes":"Maintain exact visual continuity between her established portrait, human-form production sheet, dragon form, and dragon production sheet. Future artwork should preserve her face, black hair, ocean-blue eyes, imperial aquatic aesthetic, signature palette, and Eastern-style leviathan design.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/portrait/1790319597422-shu-m-l-nhu-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nDragon Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Done\nRight View — Done\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nExpression Sheet — Needed\nCombat Reference — Needed","productionNotes":"Use the established production sheet as the primary visual reference for Lánhuá. Her human design should remain elegant, ancient, and imperial with long black hair, ocean-blue eyes, ornate aquatic hairpieces, and layered blue ceremonial robes. Her dragon form must remain a colossal Eastern-style aquatic leviathan with an elongated serpentine body, iridescent blue-teal scales, luminous aquatic mane, and water-and-mist manifestations.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/reference/1790319612245-shu-m-l-nhu-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/alternate/1790319622886-shu-m-l-nhu-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/portrait/1790319597422-shu-m-l-nhu-character-portrait.png',6,1,1,'065f06b5-4812-4543-9430-02830d72ae0b','f0c6ce62-f547-4fc2-8765-6a9f8bebc590','9eabcca3-b901-4fdb-92da-03d6ab2a98c5','3e083a30-190f-4d2e-a61c-605c24c21769','2026-09-25T08:15:14.874796+00:00');
